import ts from "typescript"

const code = `export const price: number = "100"`   // tip xatosi bor

function build(options: ts.CompilerOptions) {
    const written: string[] = []
    const host = ts.createCompilerHost({})
    const orig = host.getSourceFile
    host.getSourceFile = (n, l) => (n === "a.ts" ? ts.createSourceFile(n, code, l) : orig(n, l))
    host.writeFile = (name) => { written.push(name) }
    const program = ts.createProgram(["a.ts"], { skipLibCheck: true, types: [], ...options }, host)
    const errors = ts.getPreEmitDiagnostics(program).filter(d => d.file?.fileName === "a.ts").length
    const { emitSkipped } = program.emit()
    return { errors, emitSkipped, written }
}

console.log("standart:      ", build({}))
console.log("noEmitOnError: ", build({ noEmitOnError: true }))
console.log("noEmit:        ", build({ noEmit: true }))

