import ts from "typescript"

const withoutOverride = `class Animal { speak() { return "..." } }
class Dog extends Animal { speak() { return "Vov" } }`
const withOverride = `class Animal { speak() { return "..." } }
class Dog extends Animal { override speak() { return "Vov" } }`

function diagnostics(code: string) {
    const host = ts.createCompilerHost({})
    const orig = host.getSourceFile
    host.getSourceFile = (n, l) => (n === "a.ts" ? ts.createSourceFile(n, code, l) : orig(n, l))
    const program = ts.createProgram(["a.ts"], { noEmit: true, skipLibCheck: true, types: [], noImplicitOverride: true }, host)
    return ts.getPreEmitDiagnostics(program).filter(d => d.file?.fileName === "a.ts")
        .map(d => ts.flattenDiagnosticMessageText(d.messageText, " "))
}

console.log("override'siz →", diagnostics(withoutOverride))
console.log("override bilan →", diagnostics(withOverride))

